688:    private List<Column> getFileSchema() throws DdlException {
689:        if (fileStatuses.isEmpty()) {
690:            return Lists.newArrayList();
691:        }
692:        TNetworkAddress address;
693:        List<Long> nodeIds = GlobalStateMgr.getCurrentState().getNodeMgr().getClusterInfo().getBackendIds(true);
694:        if (RunMode.isSharedDataMode()) {
695:            nodeIds.addAll(GlobalStateMgr.getCurrentState().getNodeMgr().getClusterInfo().getComputeNodeIds(true));
696:        }
697:        if (nodeIds.isEmpty()) {
698:            if (RunMode.isSharedNothingMode()) {
699:                throw new DdlException("Failed to send proxy request. No alive backends");
700:            } else {
701:                throw new DdlException("Failed to send proxy request. No alive backends or compute nodes");
702:            }
703:        }
704:
705:        Collections.shuffle(nodeIds);
706:        ComputeNode node = GlobalStateMgr.getCurrentState().getNodeMgr().getClusterInfo().getBackendOrComputeNode(nodeIds.get(0));
707:        address = new TNetworkAddress(node.getHost(), node.getBrpcPort());
708:
709:        PGetFileSchemaResult result;
710:        try {
711:            PGetFileSchemaRequest request = getGetFileSchemaRequest(fileStatuses);
712:            Future<PGetFileSchemaResult> future = BackendServiceClient.getInstance().getFileSchema(address, request);
713:            result = future.get();
714:        } catch (InterruptedException e) {
715:            Thread.currentThread().interrupt();
716:            throw new DdlException("failed to get file schema", e);
717:        } catch (Exception e) {
718:            throw new DdlException("failed to get file schema: " + e.getMessage());
719:        }
720:
721:        if (TStatusCode.findByValue(result.status.statusCode) != TStatusCode.OK) {
722:            throw new DdlException("failed to get file schema, path: " + path + ", error: " + result.status.errorMsgs);
723:        }
724:
725:        List<Column> columns = new ArrayList<>();
726:        for (PSlotDescriptor slot : result.schema) {
727:            columns.add(new Column(slot.colName, TypeDeserializer.fromProtobuf(slot.slotType), true));
728:        }
729:        return columns;
730:    }
