13:/// Reads a parquet file's footer and maps each top-level column to a StarRocks slot descriptor.
14:pub(crate) async fn parquet_file_schema(path: &str) -> Result<Vec<PSlotDescriptor>, String> {
15:    let local = local_file_path(path)?;
16:    let file = tokio::fs::File::open(&local)
17:        .await
18:        .map_err(|err| format!("failed to open {local}: {err}"))?;
19:    let builder = ParquetRecordBatchStreamBuilder::new(file)
20:        .await
21:        .map_err(|err| format!("failed to read parquet metadata from {local}: {err}"))?;
22:    // Iterate the top-level fields (not physical leaves) so column names and nesting are preserved.
23:    let slots = builder
24:        .metadata()
25:        .file_metadata()
26:        .schema_descr()
27:        .root_schema()
28:        .get_fields()
29:        .iter()
30:        .enumerate()
31:        .map(|(idx, field)| {
32:            Ok(slot_descriptor(
33:                idx as i32,
34:                field.name(),
35:                scalar_type(field)?,
36:            ))
37:        })
38:        .collect::<Result<Vec<_>, String>>()?;
39:    // StarRocks resolves column names case-insensitively, so names colliding only by case
40:    // would be ambiguous; the native scanner rejects them too.
41:    let mut seen = std::collections::HashSet::new();
42:    for slot in &slots {
43:        if !seen.insert(slot.col_name.to_ascii_lowercase()) {
44:            return Err(format!(
45:                "column name '{}' collides case-insensitively with another column",
46:                slot.col_name
47:            ));
48:        }
49:    }
50:    Ok(slots)
51:}
