53:/// Infers one schema for a multi-file FILES() call.
54:///
55:/// The schema comes from the first file; every other file must agree on column names
56:/// (ASCII case-insensitive, matching StarRocks name resolution) and types. Positional
57:/// slot fields (id/slot_idx/column_pos) are per-file bookkeeping and are not compared.
58:///
59:/// Deliberately stricter than native StarRocks, which samples `schema_sample_file_count`
60:/// files and promotes conflicting types: the scan reads every file with the inferred
61:/// schema, so whole-set agreement is the correct fail-closed contract here.
62:pub(crate) async fn parquet_files_schema(paths: &[String]) -> Result<Vec<PSlotDescriptor>, String> {
63:    let (first, rest) = paths
64:        .split_first()
65:        .ok_or_else(|| "no file paths to infer a schema from".to_string())?;
66:    let slots = parquet_file_schema(first).await?;
67:    for path in rest {
68:        let other = parquet_file_schema(path).await?;
69:        if other.len() != slots.len() {
70:            return Err(format!(
71:                "FILES() schema mismatch: '{path}' has {} columns but '{first}' has {}",
72:                other.len(),
73:                slots.len()
74:            ));
75:        }
76:        for (idx, (expected, found)) in slots.iter().zip(&other).enumerate() {
77:            if !expected.col_name.eq_ignore_ascii_case(&found.col_name) {
78:                return Err(format!(
79:                    "FILES() schema mismatch: column {idx} is named '{}' in '{first}' but '{}' in '{path}'",
80:                    expected.col_name, found.col_name
81:                ));
82:            }
83:            if expected.slot_type != found.slot_type {
84:                return Err(format!(
85:                    "FILES() schema mismatch: column '{}' has a different type in '{path}' than in '{first}'",
86:                    expected.col_name
87:                ));
88:            }
89:        }
90:    }
91:    Ok(slots)
92:}
