94:/// Resolves a StarRocks file path to a local filesystem path, rejecting remote URIs.
95:///
96:/// Accepts `file:/abs`, `file:///abs`, and `file://localhost/abs`; remote schemes
97:/// (s3://, hdfs://, ...) and non-local file authorities need broker handling, not yet wired.
98:fn local_file_path(path: &str) -> Result<String, String> {
99:    if let Some(rest) = path.strip_prefix("file://") {
100:        // `file:///abs` has an empty authority; `file://host/abs` has one before the path.
101:        if rest.starts_with('/') {
102:            return Ok(rest.to_string());
103:        }
104:        let authority = rest.split('/').next().unwrap_or(rest);
105:        if authority == "localhost" {
106:            return Ok(rest[authority.len()..].to_string());
107:        }
108:        return Err(format!("file URI authority '{authority}' is not local"));
109:    }
110:    if let Some(rest) = path.strip_prefix("file:") {
111:        return Ok(rest.to_string());
112:    }
113:    if let Some((scheme, _)) = path.split_once("://") {
114:        return Err(format!(
115:            "remote path scheme '{scheme}://' is not supported yet; only local file paths are implemented"
116:        ));
117:    }
118:    Ok(path.to_string())
119:}
