121:/// Maps one top-level parquet field to a StarRocks scalar type, preferring the logical type.
122:fn scalar_type(field: &Type) -> Result<PScalarType, String> {
123:    if !field.is_primitive() {
124:        return Err(format!(
125:            "column '{}' has a nested parquet type; only flat columns are supported",
126:            field.name()
127:        ));
128:    }
129:    if let Some(logical) = field.get_basic_info().logical_type_ref() {
130:        return Ok(match logical {
131:            LogicalType::String | LogicalType::Enum | LogicalType::Uuid => varchar(),
132:            LogicalType::Bson => varbinary(),
133:            LogicalType::Json => primitive(TPrimitiveType::JSON),
134:            LogicalType::Decimal(d) => decimal(d.precision, d.scale),
135:            LogicalType::Date => primitive(TPrimitiveType::DATE),
136:            LogicalType::Time(_) => primitive(TPrimitiveType::TIME),
137:            LogicalType::Timestamp(_) => primitive(TPrimitiveType::DATETIME),
138:            // Integers (incl. unsigned/sub-width) follow the native mapping: by physical width.
139:            _ => physical_scalar_type(field),
140:        });
141:    }
142:    Ok(physical_scalar_type(field))
143:}
144:
145:/// Maps a field without a logical-type annotation via its converted/physical type.
146:fn physical_scalar_type(field: &Type) -> PScalarType {
147:    match field.get_basic_info().converted_type() {
148:        ConvertedType::UTF8 | ConvertedType::ENUM => return varchar(),
149:        ConvertedType::BSON => return varbinary(),
150:        ConvertedType::JSON => return primitive(TPrimitiveType::JSON),
151:        ConvertedType::DECIMAL => return decimal(field.get_precision(), field.get_scale()),
152:        ConvertedType::DATE => return primitive(TPrimitiveType::DATE),
153:        ConvertedType::TIMESTAMP_MILLIS | ConvertedType::TIMESTAMP_MICROS => {
154:            return primitive(TPrimitiveType::DATETIME);
155:        }
156:        ConvertedType::TIME_MILLIS | ConvertedType::TIME_MICROS => {
157:            return primitive(TPrimitiveType::TIME);
158:        }
159:        _ => {}
160:    }
161:    // Integer annotations (INT_8/UINT_32/...) are not special-cased: like the native reader,
162:    // integers map purely by physical width (INT32 -> INT, INT64 -> BIGINT).
163:    match field.get_physical_type() {
164:        PhysicalType::BOOLEAN => primitive(TPrimitiveType::BOOLEAN),
165:        PhysicalType::INT32 => primitive(TPrimitiveType::INT),
166:        PhysicalType::INT64 => primitive(TPrimitiveType::BIGINT),
167:        PhysicalType::INT96 => primitive(TPrimitiveType::DATETIME),
168:        PhysicalType::FLOAT => primitive(TPrimitiveType::FLOAT),
169:        PhysicalType::DOUBLE => primitive(TPrimitiveType::DOUBLE),
170:        // Raw variable byte arrays are binary; the reader accepts them as VARBINARY.
171:        PhysicalType::BYTE_ARRAY => varbinary(),
172:        // The native parquet reader only accepts fixed-length byte arrays as varchar/char/decimal.
173:        PhysicalType::FIXED_LEN_BYTE_ARRAY => varchar(),
174:    }
175:}
176:
177:/// Picks the DecimalV3 width StarRocks uses for the given precision.
178:fn decimal(precision: i32, scale: i32) -> PScalarType {
179:    let primitive = if precision <= 9 {
180:        TPrimitiveType::DECIMAL32
181:    } else if precision <= 18 {
182:        TPrimitiveType::DECIMAL64
183:    } else if precision <= 38 {
184:        TPrimitiveType::DECIMAL128
185:    } else {
186:        // The reader has no DECIMAL256 converter; native promotion falls back to varchar.
187:        return varchar();
188:    };
189:    PScalarType {
190:        r#type: primitive.0,
191:        len: None,
192:        precision: Some(precision),
193:        scale: Some(scale),
194:    }
195:}
196:
197:/// Scalar type carrying only a primitive tag (no length/precision/scale).
198:fn primitive(primitive: TPrimitiveType) -> PScalarType {
199:    PScalarType {
200:        r#type: primitive.0,
201:        len: None,
202:        precision: None,
203:        scale: None,
204:    }
205:}
206:
207:/// Inferred VARCHAR scalar type.
208:fn varchar() -> PScalarType {
209:    sized(TPrimitiveType::VARCHAR)
210:}
211:
212:/// Inferred VARBINARY scalar type.
213:fn varbinary() -> PScalarType {
214:    sized(TPrimitiveType::VARBINARY)
215:}
216:
217:/// Length-carrying scalar type (VARCHAR/VARBINARY) at the inferred max length.
218:fn sized(primitive: TPrimitiveType) -> PScalarType {
219:    PScalarType {
220:        r#type: primitive.0,
221:        len: Some(INFERRED_VARCHAR_LEN),
222:        precision: None,
223:        scale: None,
224:    }
225:}
