227:/// Wraps a scalar type in the slot descriptor the FE expects (only col_name and slot_type are read).
228:fn slot_descriptor(idx: i32, name: &str, scalar: PScalarType) -> PSlotDescriptor {
229:    PSlotDescriptor {
230:        id: idx,
231:        parent: 0,
232:        slot_type: PTypeDesc {
233:            types: vec![PTypeNode {
234:                r#type: TTypeNodeType::SCALAR.0,
235:                scalar_type: Some(scalar),
236:                struct_fields: Vec::new(),
237:            }],
238:        },
239:        column_pos: idx,
240:        byte_offset: 0,
241:        null_indicator_byte: 0,
242:        null_indicator_bit: 0,
243:        col_name: name.to_string(),
244:        slot_idx: idx,
245:        is_materialized: true,
246:        global_dict_words: Vec::new(),
247:        global_dict_version: None,
248:    }
249:}
